/**
 * Naming a visitor by a sign-in they made in the world: loaded only once they have signed in, so the page a world's
 * link opens carries none of it.
 */

/** The longest avatar URL the room keeps (WorldSync protocol §4.6). */
const AVATAR_URL_MAX = 2048;

/** An avatar URL as the room keeps one: an absolute https URL of at most 2048 characters; anything else is none. */
function wornAvatar(raw: string): string | undefined {
  if (!raw || raw.length > AVATAR_URL_MAX || !raw.startsWith('https://')) return undefined;
  try {
    return new URL(raw).protocol === 'https:' ? raw : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Hands a sign-in to the page's host (`visitor-session`) and takes back who the visitor is: the name and avatar it
 * answers, bounded as the page's own attributes are. Null when the host does not name them, or cannot be reached.
 */
export async function namedBySignIn(
  path: string,
  upstream: string,
  fetchImpl: (url: string, init?: RequestInit) => Promise<Response>,
): Promise<{ name?: string; avatar?: string } | null> {
  try {
    const res = await fetchImpl(path, { method: 'POST', headers: { authorization: `Bearer ${upstream}` } });
    if (!res.ok) return null;
    const body = (await res.json()) as { name?: unknown; avatar?: unknown };
    const name = typeof body.name === 'string' ? body.name.trim().slice(0, 40) : '';
    const avatar = typeof body.avatar === 'string' ? wornAvatar(body.avatar.trim()) : undefined;
    return { ...(name ? { name } : {}), ...(avatar ? { avatar } : {}) };
  } catch {
    return null;
  }
}
